import{_ as s,a0 as p,w as l,s as u,ao as r,I as a,x as o,a1 as n,A as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"在 Ubuntu 14.04/15.04 上配置 Node JS v4.0.0 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 14.04/15.04 上配置 Node JS v4.0.0 | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 14.04/15.04 上配置 Node JS v4.0.0 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 14.04/15.04 上配置 Node JS v4.0.0 | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20150914 How to Setup Node JS v4.0.0 on Ubuntu 14.04 or 15.04","title":"在 Ubuntu 14.04/15.04 上配置 Node JS v4.0.0","tag":"201510","desc":""},"relativePath":"201510/20150914 How to Setup Node JS v4.0.0 on Ubuntu 14.04 or 15.04.md","filePath":"[post].md"}'),i={name:"201510/20150914 How to Setup Node JS v4.0.0 on Ubuntu 14.04 or 15.04.md"};function b(m,e,h,g,N,c){const t=p("Link");return l(),u("div",null,[e[16]||(e[16]=r(`<h1 id="在-ubuntu-14-04-15-04-上配置-node-js-v4-0-0" tabindex="-1">在 Ubuntu 14.04/15.04 上配置 Node JS v4.0.0 <a class="header-anchor" href="#在-ubuntu-14-04-15-04-上配置-node-js-v4-0-0" aria-label="Permalink to “在 Ubuntu 14.04/15.04 上配置 Node JS v4.0.0”">​</a></h1><p>大家好，Node.JS 4.0 發佈了，這個流行的服務器端 JS 平台合併了 Node.js 和 io.js 的代碼，4.0 版就是這兩個項目結合的產物——現在合併為一個代碼庫。這次最主要的變化是 Node.js 封裝了4.5 版本的 Google V8 JS 引擎，與當前的 Chrome 所帶的一致。所以，緊跟 V8 的發佈可以讓 Node.js 運行的更快、更安全，同時更好的利用 ES6 的很多語言特性。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/nodejs.png" alt="Node JS"></p><p>Node.js 4.0 發佈的主要目標是為 io.js 用户提供一個簡單的升級途徑，所以這次並沒有太多重要的 API 變更。下面的內容讓我們來看看如何輕鬆的在 ubuntu server 上安裝、配置 Node.js。</p><h3 id="基礎系統安裝" tabindex="-1">基礎系統安裝 <a class="header-anchor" href="#基礎系統安裝" aria-label="Permalink to “基礎系統安裝”">​</a></h3><p>Node 在 Linux，Macintosh，Solaris 這幾個系統上都可以完美的運行，linux 的發行版本當中使用 Ubuntu 相當適合。這也是我們為什麼要嘗試在 ubuntu 15.04 上安裝 Node.js，當然了在 14.04 上也可以使用相同的步驟安裝。</p><h4 id="_1-系統資源" tabindex="-1">1) 系統資源 <a class="header-anchor" href="#_1-系統資源" aria-label="Permalink to “1) 系統資源”">​</a></h4><p>Node.js 所需的基本的系統資源取決於你的架構需要。本教程我們會在一台 1GB 內存、 1GHz 處理器和 10GB 磁盤空間的服務器上進行，最小安裝即可，不需要安裝 Web 服務器或資料庫服務器。</p><h4 id="_2-系統更新" tabindex="-1">2) 系統更新 <a class="header-anchor" href="#_2-系統更新" aria-label="Permalink to “2) 系統更新”">​</a></h4><p>在我們安裝 Node.js 之前，推薦你將系統更新到最新的補丁和升級包，所以請登錄到系統中使用超級用户運行如下命令：</p><pre><code># apt-get update
</code></pre><h4 id="_3-安裝依賴" tabindex="-1">3) 安裝依賴 <a class="header-anchor" href="#_3-安裝依賴" aria-label="Permalink to “3) 安裝依賴”">​</a></h4><p>Node.js 僅需要你的服務器上有一些基本系統和軟件功能，比如 &#39;make&#39;、&#39;gcc&#39;和&#39;wget&#39; 之類的。如果你還沒有安裝它們，運行如下命令安裝：</p><pre><code># apt-get install python gcc make g++ wget
</code></pre><h3 id="下載最新版的node-js-v4-0-0" tabindex="-1">下載最新版的Node JS v4.0.0 <a class="header-anchor" href="#下載最新版的node-js-v4-0-0" aria-label="Permalink to “下載最新版的Node JS v4.0.0”">​</a></h3>`,15)),a("p",null,[e[1]||(e[1]=o("訪問鏈接 ",-1)),n(t,{href:"https://nodejs.org/download/rc/v4.0.0-rc.1/"},{default:d(()=>[...e[0]||(e[0]=[o("Node JS Download Page",-1)])]),_:1}),e[2]||(e[2]=o(" 下載源代碼.",-1))]),e[17]||(e[17]=r(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/download.png" alt="nodejs download"></p><p>複製其中的最新的源代碼的鏈接，然後用<code>wget</code> 下載，命令如下：</p><pre><code># wget https://nodejs.org/download/rc/v4.0.0-rc.1/node-v4.0.0-rc.1.tar.gz
</code></pre><p>下載完成後使用命令<code>tar</code> 解壓縮：</p><pre><code># tar -zxvf node-v4.0.0-rc.1.tar.gz
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/wget.png" alt="wget nodejs"></p><h3 id="安裝-node-js-v4-0-0" tabindex="-1">安裝 Node JS v4.0.0 <a class="header-anchor" href="#安裝-node-js-v4-0-0" aria-label="Permalink to “安裝 Node JS v4.0.0”">​</a></h3><p>現在可以開始使用下載好的源代碼編譯 Node.js。在開始編譯前，你需要在 ubuntu server 上切換到源代碼解壓縮後的目錄，運行 configure 腳本來配置源代碼。</p><pre><code>root@ubuntu-15:~/node-v4.0.0-rc.1# ./configure
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/configure.png" alt="Installing NodeJS"></p><p>現在運行命令 &#39;make install&#39; 編譯安裝 Node.js：</p><pre><code>root@ubuntu-15:~/node-v4.0.0-rc.1# make install
</code></pre><p>make 命令會花費幾分鐘完成編譯，安靜的等待一會。</p><h3 id="驗證-node-js-安裝" tabindex="-1">驗證 Node.js 安裝 <a class="header-anchor" href="#驗證-node-js-安裝" aria-label="Permalink to “驗證 Node.js 安裝”">​</a></h3><p>一旦編譯任務完成，我們就可以開始驗證安裝工作是否 OK。我們運行下列命令來確認 Node.js 的版本。</p><pre><code>root@ubuntu-15:~# node -v
v4.0.0-pre
</code></pre><p>在命令列下不帶參數的運行<code>node</code> 就會進入 REPL(Read-Eval-Print-Loop,讀-執行-輸出-循環)模式，它有一個簡化版的emacs 行編輯器，通過它你可以交互式的運行JS和查看運行結果。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/node.png" alt="node version"></p><h3 id="編寫測試程序" tabindex="-1">編寫測試程序 <a class="header-anchor" href="#編寫測試程序" aria-label="Permalink to “編寫測試程序”">​</a></h3><p>我們也可以寫一個很簡單的終端程序來測試安裝是否成功，並且工作正常。要做這個，我們將會創建一個“test.js” 文件，包含以下代碼，操作如下：</p><pre><code>root@ubuntu-15:~# vim test.js
var util = require(&quot;util&quot;);
console.log(&quot;Hello! This is a Node Test Program&quot;);
:wq!
</code></pre><p>現在為了運行上面的程序，在命令列運行下面的命令。</p><pre><code>root@ubuntu-15:~# node test.js
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/node-test.png" alt="Node Program"></p><p>在一個成功安裝了 Node JS 的環境下運行上面的程序就會在屏幕上得到上圖所示的輸出，這個程序加載類 “util” 到變量 “util” 中，接着用對象 “util” 運行終端任務，console.log 這個命令作用類似 C++ 裏的cout</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>就是這些了。如果你剛剛開始使用 Node.js 開發應用程序，希望本文能夠通過在 ubuntu 上安裝、運行 Node.js 讓你瞭解一下Node.js 的大概。最後，我們可以認為我們可以期待 Node JS v4.0.0 能夠取得顯著性能提升。</p><hr>`,28)),a("p",null,[e[4]||(e[4]=o("via: ",-1)),n(t,{href:"http://linoxide.com/ubuntu-how-to/setup-node-js-4-0-ubuntu-14-04-15-04/"},{default:d(()=>[...e[3]||(e[3]=[o("http://linoxide.com/ubuntu-how-to/setup-node-js-4-0-ubuntu-14-04-15-04/",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=o("作者：",-1)),n(t,{href:"http://linoxide.com/author/kashifs/"},{default:d(()=>[...e[5]||(e[5]=[o("Kashif Siddique",-1)])]),_:1}),e[9]||(e[9]=o(" 譯者：",-1)),n(t,{href:"https://github.com/osk874"},{default:d(()=>[...e[6]||(e[6]=[o("osk874",-1)])]),_:1}),e[10]||(e[10]=o(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:d(()=>[...e[7]||(e[7]=[o("wxy",-1)])]),_:1})]),a("p",null,[e[13]||(e[13]=o("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[11]||(e[11]=[o("LCTT",-1)])]),_:1}),e[14]||(e[14]=o(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:d(()=>[...e[12]||(e[12]=[o("Linux中國",-1)])]),_:1}),e[15]||(e[15]=o(" 榮譽推出",-1))])])}const j=s(i,[["render",b]]);export{S as __pageData,j as default};
